/**
 * Vendor guide model: the Bricks Standard step-by-step guide (data/guide.json,
 * generated by the standard's tools/make_guide.py) and job matching.
 * Pure functions only (no React, no DOM, no Vite), so node tests can bundle it.
 */
export type GuideStep = {
  id: string;
  phase: string;
  title: string;
  body: string;
  diagram: string | null;
  diagram_alt: string | null;
  do: string[];
  dont: string[];
  applies_to: string[];
};
export type GuidePhase = { id: string; title: string; order: number };
export type GuideClip = {
  id: string; name: string; group: string; movement: string; capture_s: [number, number];
  speed_limit: string | null; travel_or_arc: string | null; lens_ff_mm: string | null;
  height: string | null; framing: string; when: string | null;
};
export type PackageId = 'photos' | 'essentials' | 'story' | 'showcase' | 'suite';
export type GuidePackage = { id: PackageId; name: string; includes: string[]; clips: boolean; services: string[] };
export type PropertyType = 'condo' | 'house' | 'luxury' | 'commercial';

type StoryList = {
  horizontal?: string[]; vertical?: string[]; drone?: string[]; drone_note?: string;
  repeat?: Record<string, string>; notes?: Record<string, string>;
  extends?: string; add_horizontal?: string[]; add_vertical?: string[];
};
export type GuideData = {
  title: string; version: string; intro: string;
  phases: GuidePhase[]; steps: GuideStep[]; packages: GuidePackage[]; clips: GuideClip[];
  clip_lists: {
    story: Record<PropertyType, StoryList> & { always: string[] };
    showcase: { add_horizontal: string[]; add_vertical: string[]; plus?: string };
    suite: { add_horizontal: string[] };
  };
};

export const PROPERTY_TYPES: { id: PropertyType; label: string }[] = [
  { id: 'condo', label: 'Condo' },
  { id: 'house', label: 'House' },
  { id: 'luxury', label: 'Luxury' },
  { id: 'commercial', label: 'Commercial' },
];

const PKG_ALIASES: Record<string, PackageId> = {
  photos: 'photos', photosonly: 'photos', photoonly: 'photos',
  essentials: 'essentials', essential: 'essentials',
  story: 'story',
  showcase: 'showcase',
  suite: 'suite', fullsuite: 'suite', full: 'suite',
};

function compact(v: unknown): string {
  return String(v ?? '').toLowerCase().replace(/[^a-z0-9]+/g, '');
}

/** Rate-card package for a job, or null when it is not one of the five names. */
export function jobPackage(job: { package_id?: string | null; package_name?: string | null }): PackageId | null {
  const id = compact(job.package_id);
  if (PKG_ALIASES[id]) return PKG_ALIASES[id];
  const name = String(job.package_name ?? '').toLowerCase();
  if (/\bfull suite\b/.test(name)) return 'suite';
  for (const w of ['showcase', 'story', 'essentials'] as const) if (new RegExp(`\\b${w}\\b`).test(name)) return w;
  if (/\bphotos? only\b/.test(name)) return 'photos';
  return null;
}

/** Property type from the job's free-text property details, or null. */
export function jobPropertyType(job: { property_details?: string | null }): PropertyType | null {
  const t = String(job.property_details ?? '').toLowerCase();
  if (!t) return null;
  if (/\b(commercial|office|retail|industrial|warehouse)\b/.test(t)) return 'commercial';
  if (/\b(luxury|estate)\b/.test(t)) return 'luxury';
  if (/\b(condo|loft|apartment|penthouse)\b/.test(t)) return 'condo';
  if (/\b(house|detached|semi|town ?house|townhome|freehold|bungalow)\b/.test(t)) return 'house';
  return null;
}

/** Services a job needs: its package's services, plus Virtual Visit when booked as an add-on. */
export function jobServices(pkg: PackageId | null, data: GuideData, extra: { visit?: boolean } = {}): Set<string> {
  const s = new Set<string>(['all']);
  const p = pkg ? data.packages.find((x) => x.id === pkg) : null;
  if (p) p.services.forEach((x) => s.add(x));
  if (extra.visit) s.add('virtual_visit');
  return s;
}

/** A step applies when any one of its applies_to services is booked. Null = every step. */
export function stepsForServices(data: GuideData, services: Set<string> | null): GuideStep[] {
  if (!services) return data.steps;
  return data.steps.filter((st) => st.applies_to.some((a) => services.has(a)));
}

export type ClipRow = { id: string; clip: GuideClip | null; note?: string };
export type ClipPlan = {
  horizontal: ClipRow[]; vertical: ClipRow[]; drone: ClipRow[]; reference: ClipRow[];
  droneNote?: string; total: number;
};

/** Required clip list for a package and property type. Null when the package has no film. */
export function clipPlan(data: GuideData, pkg: PackageId | null, type: PropertyType): ClipPlan | null {
  if (!pkg || pkg === 'photos' || pkg === 'essentials') return null;
  const byId = new Map(data.clips.map((c) => [c.id, c]));
  const story = data.clip_lists.story;
  const own = story[type] as StoryList;
  const base = (own.extends ? story[own.extends as PropertyType] : own) as StoryList;
  const repeat = { ...(base.repeat || {}), ...(own.repeat || {}) };
  const notes = { ...(base.notes || {}), ...(own.notes || {}) };
  const row = (raw: string, extraNote?: string): ClipRow => {
    const m = raw.match(/^([A-Z]{3}-\d{2}(?:_V)?)\s*(?:\((.*)\))?$/);
    const id = m ? m[1] : raw;
    const plain = id.replace(/_V$/, '');
    const note = [m?.[2], notes[plain], repeat[plain], extraNote].filter(Boolean).join(' · ') || undefined;
    return { id, clip: byId.get(plain) || null, note };
  };
  const uniq = (ids: string[]) => ids.filter((v, i) => ids.indexOf(v) === i);
  const horizontal = uniq([...(base.horizontal || []), ...(own.extends ? own.add_horizontal || [] : [])]);
  const vertical = uniq([...(base.vertical || []), ...(own.extends ? own.add_vertical || [] : [])]);
  const drone = own.drone || base.drone || [];
  const h = horizontal.map((x) => row(x));
  const v = vertical.map((x) => row(`${x}_V`));
  if (pkg === 'showcase' || pkg === 'suite') {
    for (const a of data.clip_lists.showcase.add_horizontal) {
      const alt = a.match(/^([A-Z]{3}-\d{2}) \(condo: ([A-Z]{3}-\d{2})\)$/); // "INT-11 (condo: INT-05)"
      h.push(row(alt ? (type === 'condo' ? alt[2] : alt[1]) : a, 'Showcase addition'));
    }
    for (const a of data.clip_lists.showcase.add_vertical) if (!vertical.includes(a)) v.push(row(`${a}_V`, 'Showcase addition'));
  }
  if (pkg === 'suite') for (const a of data.clip_lists.suite.add_horizontal) h.push(row(a, 'Full suite · sunset +10 to +30 min'));
  const d = drone.map((x) => row(x));
  const ref = [row('REF-WB', 'each lighting zone'), row('REF-TONE', 'main living space')];
  return {
    horizontal: h, vertical: v, drone: d, reference: ref,
    droneNote: own.drone_note || base.drone_note,
    total: h.length + v.length + d.length + ref.length,
  };
}

/** Diagrams are drawn on off-white. On the dark app surface: drop the bg layer, map ink to the dark palette. */
const DARK_MAP: Record<string, string> = {
  '#14110E': '#F4F1EB', // ink -> off-white
  '#615D57': '#B8B0A3', // graphite text and lines
  '#97928A': '#8F8678', // mid grey
  '#B7B2AA': '#5E574C', // guides and dashes
  '#F4F1EB': '#1C1A17', // knock-out fills -> card surface
};
export function darkDiagram(svg: string, uid: string): string {
  let out = svg.replace(/<\?xml[^>]*>\s*/, '').replace(/<rect id="bg"[^>]*\/>\s*/, '');
  out = out.replace(/#[0-9A-Fa-f]{6}\b/g, (hex) => DARK_MAP[hex.toUpperCase()] || hex);
  // ids must stay unique with several diagrams inline on one page
  out = out.replace(/id="t"/g, `id="${uid}-t"`).replace(/aria-labelledby="t"/g, `aria-labelledby="${uid}-t"`);
  // fluid: CSS sets the width, the viewBox keeps the ratio
  out = out.replace(/<svg([^>]*?)\swidth="\d+"\sheight="\d+"/, '<svg$1');
  return out;
}
